CREATE TABLE "qc" (
  "sample" TEXT NOT NULL,
  "cutadapt.percent_trimmed" REAL,
  "fastp.after_filtering_gc_content" REAL,
  "fastp.after_filtering_q30_bases" REAL,
  "fastp.after_filtering_q30_rate" REAL,
  "fastp.filtering_result_passed_filter_reads" REAL,
  "fastp.pct_adapter" REAL,
  "fastp.pct_duplication" REAL,
  "fastp.pct_surviving" REAL,
  "fastqc.avg_sequence_length" REAL,
  "fastqc.median_sequence_length" INTEGER,
  "fastqc.percent_duplicates" INTEGER,
  "fastqc.percent_fails" REAL,
  "fastqc.percent_gc" REAL,
  "fastqc.total_sequences" REAL,
  "salmon.compatible_fragment_ratio" REAL,
  "salmon.library_types" TEXT,
  "salmon.num_mapped" INTEGER,
  "salmon.percent_mapped" REAL,
  "star.mapped" REAL,
  "star.mapped_percent" REAL,
  "star.multimapped" REAL,
  "star.total_reads" REAL,
  "star.uniquely_mapped" REAL,
  "star.uniquely_mapped_percent" REAL,
  UNIQUE ("sample")
) STRICT;
